// Study notes: docs/learning/notes/main/inventory/PurchaseResult.kt.md

package com.robertwoolbright.inventory.inventory

// Why: We used the sealed interface because we have 3 possible outcomes we need to account for. Not just a success or null.

/** PurchaseResult is returned by the repository and translated by the service. */
sealed interface PurchaseResult {

    /** The SKU exists and had enough stock. */
    data class Purchased(val item: inventoryItem) : PurchaseResult

    /** There's no row for that SKU id. */
    data object SkuNotFound : PurchaseResult

    /** The row exists but has less than the requested quantity. */
    data object InsufficientStock : PurchaseResult

}

// Study notes: docs/learning/notes/main/inventory/PurchaseResult.kt.md

package com.robertwoolbright.inventory.inventory

// Why: We used the sealed interface because we have 3 possible outcomes we need to account for. Not just a success or null so returning InventoryItem? doesn't help us between when we need to throw 404 or 400.

/** PurchaseResult is returned by the repository and translated by the service. */
sealed interface PurchaseResult {

    /** The SKU exists and had enough stock. Item holds the remaining stock. */
    data class Purchased(val item: InventoryItem) : PurchaseResult

    /** There's no row for that SKU id. */
    data object SkuNotFound : PurchaseResult

    /** The row exists but has less than the requested quantity. */
    data object InsufficientStock : PurchaseResult

}

            }
            .list().singleOrNull()


    /** 
     * Removes the requested quantity because of a purchase from the inventory database for a selected SKU. 
     * Returns the updated inventoryItem if successful, InsufficientStock object if not enough quantity for the purchase, and SkuNotFound object if skuId was not found.
     */
    fun removeStock(skuId: String, quantity: Int): PurchaseResult = jdbcClient.sql(
        // Why: One statement instead of 2 (update then select) so we don't deal with racing condition and things don't change between the two mid logic.
        """
            WITH purchased AS (
                UPDATE inventory SET quantity = quantity - :requested_quantity
                    WHERE sku_id = :skuId AND quantity >= :requested_quantity
                        RETURNING quantity
            )
            SELECT 
                (SELECT quantity FROM purchased) AS remaining_quantity,
                    EXISTS (SELECT 1 FROM inventory WHERE sku_id = :skuId) AS sku_exists
        """
        )
        .param("skuId", skuId)
        .param("requested_quantity", quantity)
        .query{rs, _ ->
                // Why: Used the javaObjectType so null stays null. Regular Kotlin getInt would turn null into 0, but 0 is a valid use case here. Meaning out of stock.
                val remainingQuantity: Int? = rs.getObject("remaining_quantity", Int::class.javaObjectType) 
                    val skuExists = rs.getBoolean("sku_exists")
                        when {
                            remainingQuantity != null -> PurchaseResult.Purchased(InventoryItem(skuId, remainingQuantity))
                            skuExists -> PurchaseResult.InsufficientStock
                            else -> PurchaseResult.SkuNotFound
                        }
        }
        .single()
}
